return [
    'up' => function (PDO $db) use ($photos) {
        $db->exec("ALTER TABLE devices ADD COLUMN image_credit VARCHAR(255) NULL AFTER image, ADD COLUMN image_source VARCHAR(255) NULL AFTER image_credit");
        $st = $db->prepare("UPDATE devices SET image = ?, image_credit = ?, image_source = ? WHERE word = ?");
        foreach ($photos as [$word, $path, $credit, $source]) $st->execute([$path, $credit, $source, $word]);
    },
    'down' => function (PDO $db) use ($photos) {
        $st = $db->prepare("UPDATE devices SET image = NULL WHERE word = ? AND image = ?");
        foreach ($photos as [$word, $path]) $st->execute([$word, $path]);
        $db->exec("ALTER TABLE devices DROP COLUMN image_credit, DROP COLUMN image_source");
    },
];
